head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.contnId = "";
scwin.market = $c.session.getUserInfo("market");
scwin.wrtId = $c.session.getUserInfo("empNo")

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init, singleRead, fn_SetIrInfoHeader 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        muc.setMaxFileCount(3) ;
        ibx_wrtr_id.hide();
        ibx_page_gbn.hide();

        ibx_wrt_dd.show("");
        ibx_file_name.hide();

        scwin.init(); // 시장구분

        scwin.param = $c.data.getParameter();
        scwin.displayFlag = scwin.param.flag;
        scwin.contnId  = $c.data.getParameter("contnId");

        // 수정화면 onload
        if (scwin.displayFlag === "R") {

            scwin.singleRead(); // 개별조회 호출

            if (rdo_kosdaq_bbs_tp_cd.getValue() === "10") {
                // 기업분석보고서
                ibx_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue()  === "12") {
                // 신규상장기업분석보고서
                ibx_page_gbn.setValue("report5");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "23") {
                // 기업분석보고서(영문)
                ibx_page_gbn.setValue( "report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                // 성장성보고서
                ibx_page_gbn.setValue( "report5");
            } else {
                ibx_page_gbn.setValue( "report2");
            }
            if (rdo_kosdaq_bbs_tp_cd.getValue() === "10" || rdo_kosdaq_bbs_tp_cd.getValue() === "23") {
                // 기업분석보고서, 기업분석보고서(영문), 성장성보고서
                lbl_approv_yn.hide();
                rdo_approv_yn.hide();
            } else {
                lbl_approv_yn.show("");
                rdo_approv_yn.show("");
            }
        } else {     // 등록화면 onload

            btn_delete.hide();
            lbl_approv_yn.hide();
            rdo_approv_yn.hide();

            // scwin.fn_SetIrInfoHeader();
            // dts_fileList.SetDataHeader("fileInfo:String,fileUrl:URL,filename__String,filesize__String");
            scwin.fileRowcount = 0;
            ibx_wrtr_id.setValue(scwin.wrtId);
            ibx_wrt_dd.setValue($c.date.getServerDateTime("yyyymmdd"));

            if (rdo_kosdaq_bbs_tp_cd.getValue() === "10") {
                // 기업분석보고서
                ibx_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "12") {
                // 신규상장기업분석보고서
                ibx_page_gbn.setValue("report5");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "23") {
                // 기업분석보고서(영문)
                ibx_page_gbn.setValue("report2");
            } else if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                // 성장성보고서
                ibx_page_gbn.setValue("report5");
            } else {
                ibx_page_gbn.setValue("report2");
            }
            if (scwin.market === "1" || scwin.market === "2" || scwin.market === "6") {
                rdo_mkt_tp_cd.setValue(scwin.market) ;  // 시장구분
                rdo_mkt_tp_cd.setDisabled(true);
            } else {
                rdo_mkt_tp_cd.setValue('1');
                rdo_mkt_tp_cd.setDisabled(false);
            }
            rdo_kosdaq_bbs_tp_cd.setValue('10'); // 보고서구분 : 디폴트 기업분석보고서

        }
        //  $c.cm.comIsurNm(acb_isurCd, txb_com_abbrv);

        // 컴포넌트 객체 전달
        $c.date.checkCalendarFormat("cal_noti_dd", "yyyyMMdd");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function(e) {
    try {
        IsurcdSearch_IR(acb_isurCd, txb_com_abbrv);
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            if (scwin.contnId === 'input') {
                setObjectValue(ibx_title, getObjectValue(txb_com_abbrv) + " 기업의 사업모델 평가보고서 및 기업 계속성 보고서");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.img_com_srch_onclick" });
    }
};

/**
 * @method
 * @name trs_Update_OnSuccess
 * @description trs_Update 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Update_OnSuccess = function() {
    try {
        $c.win.alert($c.data.getMessage("MSG-A001", "수정"));
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Update_OnSuccess" });
    }
};

/**
 * @method
 * @name save_onclick
 * @description 저장,수정
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.save_onclick = function(e) {
    try {
        if (scwin.displayFlag !== "C") {
            scwin.update();
        } else {
            scwin.save();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.save_onclick" });
    }
};

/**
 * @method
 * @name btn_delete_onclick
 * @description 삭제 — 「삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_delete_onclick = function(e) {
    try {
        scwin.delete();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.btn_delete_onclick" });
    }
};

/**
 * @method
 * @name trs_Delete_OnSuccess
 * @description trs_Delete 트랜잭션 성공 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Delete_OnSuccess = function() {
    try {
        $c.win.alert($c.data.getMessage("MSG-A001", "삭제"));
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Delete_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Delete_OnFail
 * @description trs_Delete 트랜잭션 실패 콜백(레거시 Gauce)
 * @returns {void}
 * @hidden N
 */
scwin.trs_Delete_OnFail = function() {
    try {
        $c.win.alert($c.data.getMessage("MSG-A002", "삭제"));
        $c.win.alert(trs_Delete.ErrorMsg);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.trs_Delete_OnFail" });
    }
};

/**
 * @method
 * @name cancel_onclick
 * @description 닫기
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.cancel_onclick = function(e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.cancel_onclick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description btn_lineadd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_lineadd_onclick = function(e) {
    try {
        if (scwin.contnId !== "input") {
            scwin.fileRowcount = dts_fileList.CountRow;
        }
        scwin.fileRowcount++;
        if (scwin.fileRowcount >= 4) {
            $c.win.alert("더이상 추가하실수 없습니다.");
            scwin.fileRowcount = 4;
        } else {
            dts_fileList.insertRow();
            inf_find.open();
            if (inf_find.getValue() !== "") {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: dts_fileList.NameString(dts_fileList.rowposition, "fileInfo") = inf_find.Value;*/
                X = inf_find.getValue(); /*ORG SRC: dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;*/ X = dts_fileList.rowposition;
                ibx_file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.DeleteRow(dts_fileList.RowPosition);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function(e) {
    try {
        if (scwin.fileRowcount > 0) scwin.fileRowcount--;
        dts_fileList.deleterow(dts_fileList.rowposition);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        //
        // ********************************************************************

        const filenm = file_name.getValue(); /*ORG SRC: dts_fileList.NameString(dts_fileList.rowposition, "fileInfo") = inf_find.Value;*/ X = inf_find.getValue();
        file_name.setValue(inf_find.getValue());
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.inf_find_OnClick" });
    }
};

/**
 * @method
 * @name grd_fileList_OnClick
 * @description grd_fileList 클릭 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_OnClick = function(row, colid) {
    try {
        if (row === 0) return;
        if (dts_fileList.RowStatus(dts_fileList.RowPosition) === 0) {
            scwin.filedown(dts_fileList.NameString(row, "ATTACH_SEQ"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.grd_fileList_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd_com_isur 키 입력 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        fn_com_Confirm_set();
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            if (scwin.displayFlag === 'C') {
                ibx_title.setValue("기업의 사업모델 평가보고서 및 기업 계속성 보고서");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd_com_isur 포커스 진입 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 — 입력값 검증·포맷
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name acb_isurCd_onblur
 * @description acb_isurCd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.acb_isurCd_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (acb_isurCd.getValue() === "") {
            txb_com_abbrv.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.acb_isurCd_onblur" });
    }
};

/**
 * @method
 * @name acb_isurCd_onfocus
 * @description acb_isurCd 포커스 진입 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.acb_isurCd_onfocus = function(e) {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.acb_isurCd_onfocus" });
    }
};

/**
 * @method
 * @name acb_isurCd_onkeyup
 * @description acb_isurCd 키 입력 해제 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.acb_isurCd_onkeyup = function() {
    try {
        if (acb_isurCd.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.Focus();
            } else {
                $c.cm.comIsurNm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.acb_isurCd_onkeyup" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description MxDataSet_com_isur 필터 조건 판정(레거시 Gauce)
 * @param {Number} row 행 인덱스
 * @returns {Boolean} 판정 결과
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.NameString(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.NameString(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name icn_SCal_onclick
 * @description icn_SCal 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.icn_SCal_onclick = function(e) {
    try {
        popUpCalendar2(cal_noti_dd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.icn_SCal_onclick" });
    }
};

/**
 * @method
 * @name rdo_kosdaq_bbs_tp_cd_onclick
 * @description rdo_kosdaq_bbs_tp_cd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_kosdaq_bbs_tp_cd_onclick = function() {
    try {
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "12" || rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            // 신규상장기업분석보고서,성장성보고서
            lbl_approv_yn.show("");
            rdo_approv_yn.show("");
            ibx_page_gbn.setValue("report5")
            if (scwin.displayFlag === 'C') {
                if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                    ibx_title.setValue("기업의 사업모델 평가보고서 및 기업 계속성 보고서") ;
                }
            }
        } else {
            lbl_approv_yn.hide();
            rdo_approv_yn.hide();
            // rdo_approv_yn.setValue();
            ibx_page_gbn.setValue("report2");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.rdo_kosdaq_bbs_tp_cd_onclick" });
    }
};

/**
 * @method
 * @name rdo_kosdaq_bbs_tp_cd_onchange
 * @description rdo_kosdaq_bbs_tp_cd 값 변경 이벤트
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.rdo_kosdaq_bbs_tp_cd_onchange = function (info) {
    try {
        if (rdo_kosdaq_bbs_tp_cd.getValue() === "12" || rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
            // 신규상장기업분석보고서,성장성보고서
            lbl_approv_yn.show("");
            rdo_approv_yn.show("");
            ibx_page_gbn.setValue("report5")
            if (scwin.displayFlag === 'C') {
                if (rdo_kosdaq_bbs_tp_cd.getValue() === "13") {
                    ibx_title.setValue("기업의 사업모델 평가보고서 및 기업 계속성 보고서") ;
                }
            }
        } else {
            lbl_approv_yn.hide();
            rdo_approv_yn.hide();
            // rdo_approv_yn.setValue();
            ibx_page_gbn.setValue("report2");
            // ibx_title.setValue("") ;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.rdo_kosdaq_bbs_tp_cd_onchange" });
    }
};

/**
 * @method
 * @name btn_isurCd_onclick
 * @description 기업검색팝업
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_isurCd_onclick = function (e) {
    try {

        $c.cm.isurcdSearch(acb_isurCd, ibx_isurCdNm);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.btn_isurCd_onclick" });
    }
};

/**
 * @method
 * @name mUpBtn_onclick
 * @description 파일추가 — 「파일선택」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.mUpBtn_onclick = function (e) {
    try {
        $c.util.onUploadClick(muc);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.mUpBtn_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 파일삭제 UI에서만 삭제 됨 — 「파일삭제」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function(e) {
    try {
            let idxArrJson = grd_fileList.getCheckedJSON("chk");
        let idxArrIndex = grd_fileList.getCheckedIndex( "chk" );
        for( let i=0;i<idxArrJson.length;i++ ) {
            let fileName = idxArrJson[i].attachFileNm;
            muc.removeFile( fileName );
        }

        dlt_FileInfoList.setBroadcast(false);
        for(let i = idxArrIndex.length - 1; i >=0; i--) {
            dlt_FileInfoList.deleteRow( idxArrIndex[i] );
        }
        dlt_FileInfoList.setBroadcast(true, true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.btn_linedelete_onclick" });
    }
};

