/**
 * @method
 * @name grd_fileList_oncellclick
 * @description 파일 다운로드
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_fileList_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        if(columnId === "attachFileLogclNm") {

            let contnId = scwin.contnId;
            let seq = dlt_FileInfoList.getCellData(rowIndex, "seq");
            let fileName = dlt_FileInfoList.getCellData(rowIndex, "attachFileLogclNm");
            const url = "/api/listing/lstproc/frgn-com-anl-rpt/receipt/file-download";

            const param = {
                            contnId : contnId
                            ,seq : seq
                        };

            $c.data.downFile(url, fileName, param)
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF07245.grd_fileList_oncellclick" });
    }
};

