/**
 * @method
 * @name singleRead
 * @description 상세조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.singleRead = async function() {

    dma_searchReq.set("contnId",scwin.contnId) ; // 게시판일련번호

    const sbmOptions = {
        id : "sbm_frgnComAnlRptDetail",
        action : "/api/listing/lstproc/frgn-com-anl-rpt/receipt/select-one",
        method : "get",
        ref : "dma_searchReq",
        target : "dma_insertReqRes=body, dlt_FileInfoList=body.attachFiles",
        isProcessMsg : false
    };

        const res  =  await $c.sbm.executeDynamic(sbmOptions);

        if(res.responseJSON.success) {
        const fileSize =  res.responseJSON.body.attachFiles.length;
        if(fileSize > 0) {
            dlt_FileInfoList.setBroadcast(false);
            for(i = 0; i < fileSize; i ++ ) {
                dlt_FileInfoList.setCellData(i, "no", i+1);
            }
            dlt_FileInfoList.setBroadcast(true, true);
        }
    }
};

