/**
 * @method
 * @name selectCallback
 * @description 파일업로드시 파일정보 dataList에 세팅
 * @returns {void}
 * @hidden N
 */
scwin.selectCallback = function() {

    let fileInfos = muc.getFileInfos();
    let stratRow = dlt_FileInfoList.getRowCount();
    dlt_FileInfoList.setBroadcast(false);
    for (i = 0; i < fileInfos.length; i++ ) {
        dlt_FileInfoList.insertRow(stratRow + i);
        dlt_FileInfoList.setCellData(stratRow + i, "no",stratRow + i + 1) ;
        dlt_FileInfoList.setCellData(stratRow + i, "seq", stratRow + i);
        dlt_FileInfoList.setCellData(stratRow + i, "attachFileLogclNm", fileInfos[i].name);
    }
    dlt_FileInfoList.setBroadcast(true, true);
    grd_fileList.setFocusedCell(0,0);
}

