/**
 * @method
 * @name update
 * @description 입력값을 수정 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    // 기업분석보고서/신규상장기업분석보고서 수정

    const options = {
            validateType : "alert",
            checkType : "single",
            focus : true,
            fields : {
                acb_isurCd : { required : true, name : "회사명"   },
                ibx_wrt_inst_nm  : { maxLength : 80, name : "작성기관" },
                ibx_title : { required : true, maxLength : 200, name : "제목" },
                txa_contn : { maxLength : 2000 ,format : "내용" },
                cal_noti_dd : { required : true, format : "date" , name : "게시일자"},
            }
    };

    const result = await $c.validate.validateDataCollect(grp_Top, options);

    if (!result) {
        return false;
    }

    const rtn = await $c.win.confirm('내용을 수정 하시겠습니까?');

    if (rtn) {
        muc.changeAction("/api/listing/lstproc/frgn-com-anl-rpt/receipt/modify");	// 수정

        const frgnComAnlRptModifyRequestDto  = {

            kosdaqBbsTpCd : dma_insertReqRes.get("kosdaqBbsTpCd") // 코스닥게시판구분코드
        , title         : dma_insertReqRes.get("title") // 제목
        , maindocContn  : dma_insertReqRes.get("maindocContn")// 본문내용
        , inqCnt  : dma_insertReqRes.get("inqCnt")// 조회수
        , isurCd  : dma_insertReqRes.get("isurCd")// 발행기관코드
        , isuCd  : dma_insertReqRes.get("isuCd") // 종목코드
        , isuNm  : dma_insertReqRes.get("isuNm") // 종목명
        , wrtInstNm  : dma_insertReqRes.get("wrtInstNm") // 작성기관명
        , wrtrId  : dma_insertReqRes.get("empNo")  // 작성자ID
        , wrtDd  : dma_insertReqRes.get("wrtDd")  // 작성일자
        , notiDd  : dma_insertReqRes.get("notiDd") // 게시일자
        , reportGbn  : dma_insertReqRes.get("reportGbn")// reportGbn
        , contnId  : scwin.contnId // reportGbn
        , mktTpCd  : dma_insertReqRes.get("mktTpCd")// 시장구분코드
        , fileInfoList :  dlt_FileInfoList.getAllJSON()	// 첨부파일
        }
        muc.setParam(0, "frgnComAnlRptModifyRequestDto", JSON.stringify(frgnComAnlRptModifyRequestDto));

        muc.startUpload();
    }

};

/**
 * @method
 * @name save
 * @description 입력값을 저장한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 기업분석보고서/신규상장기업분석보고서 등록
    /* 파일업로드 */

    const options = {
            validateType : "alert",
            checkType : "single",
            focus : true,
            fields : {
                acb_isurCd : { required : true, name : "회사명"   },
                ibx_wrt_inst_nm  : { maxLength : 80, name : "작성기관" },
                ibx_title : { required : true, maxLength : 200, name : "제목" },
                txa_contn : { maxLength : 2000 ,format : "내용" },
                cal_noti_dd : { required : true, format : "date" , name : "게시일자"},
            }
    };

    const result = await $c.validate.validateDataCollect(grp_Top, options);

    if (!result) {
        return false;
    }

    const rtn = await $c.win.confirm('위사항을 입력 하시겠습니까?');

    if(rtn) {

            muc.changeAction("/api/listing/lstproc/frgn-com-anl-rpt/receipt/register");	// action 설정

            const frgnComAnlRptRegisterRequestDto = {

                kosdaqBbsTpCd : dma_insertReqRes.get("kosdaqBbsTpCd") // 코스닥게시판구분코드
                , title         : dma_insertReqRes.get("title") // 제목
                , maindocContn  : dma_insertReqRes.get("maindocContn")// 본문내용
                , inqCnt  : dma_insertReqRes.get("inqCnt")// 조회수
                , isurCd  : dma_insertReqRes.get("isurCd")// 발행기관코드
                , isuCd  : dma_insertReqRes.get("isuCd") // 종목코드
                , isuNm  : dma_insertReqRes.get("isuNm") // 종목명
                , wrtInstNm  : dma_insertReqRes.get("wrtInstNm") // 작성기관명
                , wrtrId  : dma_insertReqRes.get("empNo")  // 작성자ID
                , wrtDd  : dma_insertReqRes.get("wrtDd")  // 작성일자
                , notiDd  : dma_insertReqRes.get("notiDd") // 게시일자
                , reportGbn  : dma_insertReqRes.get("reportGbn")// reportGbn
                , mktTpCd  : dma_insertReqRes.get("mktTpCd")// 시장구분코드
                , fileInfoList :  dlt_FileInfoList.getAllJSON()	// 첨부파일
            }

            muc.setParam(0, "frgnComAnlRptModifyRequestDto", JSON.stringify(frgnComAnlRptRegisterRequestDto));

            muc.setParam(0, "kosdaqBbsTpCd", dma_insertReqRes.get("kosdaqBbsTpCd"));	// 코스닥게시판구분코드
            muc.setParam(1, "title", dma_insertReqRes.get("title"));// 제목
            muc.setParam(2, "maindocContn", dma_insertReqRes.get("maindocContn")); // 본문내용
            muc.setParam(3, "inqCnt", dma_insertReqRes.get("inqCnt")); // 조회수
            muc.setParam(4, "isurCd",  dma_insertReqRes.get("isurCd")); // 발행기관코드
            muc.setParam(5, "isuCd", dma_insertReqRes.get("isuCd"));	 // 종목코드
            muc.setParam(6, "isuNm", dma_insertReqRes.get("isuNm"));	 // 종목명
            muc.setParam(7, "mktTpCd", dma_insertReqRes.get("mktTpCd")); // 시장구분코드
            muc.setParam(8, "wrtrId",  $c.session.getUserInfo("empNo")); // 작성자ID
            muc.setParam(9, "wrtDd", dma_insertReqRes.get("wrtDd"));// 작성일자
            muc.setParam(10, "notiDd", dma_insertReqRes.get("notiDd")); // 게시일자
            muc.setParam(11, "reportGbn", dma_insertReqRes.get("reportGbn")); // reportGbn
            muc.setParam(12, "wrtInstNm", dma_insertReqRes.get("wrtInstNm")); // 작성기관명

            muc.startUpload();

    }

};

